from lib import *
S = SS('h5')
steps = [
    step("线上 grpc-timeout 头的写法(数字最多 8 位,后面跟一个单位字母:n 纳秒、u 微秒、m 毫秒、S 秒、M 分、H 时):context 超时 50 ms → 49994167n;1 秒 → 999978u;5 秒 → 4999984u;1 分 30 秒 → 89999969u;2 小时 → 7200000m;100 小时 → 360000S。写进去的是调用发出那一刻 context 里剩下的时间(所以是 999978u 而不是 1000000u),单位随数值大小选择,让数字不超过 8 位。不设截止时间(context.Background())时请求头里没有 grpc-timeout。", t=tl(S(1)), done=lidx(S(1), 'context 超时 1s '), mark=lidx(S(1), '不设截止时间'), b=bars([['50 ms → 数字位数', 8, '49994167n'], ['1 s → 数字位数', 6, '999978u'], ['2 h → 数字位数', 7, '7200000m'], ['100 h → 数字位数', 6, '360000S']], 9, done=[1, 2, 3], mark=[0]), kv=KV([['格式', '最多 8 位数字 + 单位字母 n/u/m/S/M/H'], ['数值', '发出那一刻剩下的时间(999978u 而不是 1000000u)'], ['没有截止时间', '请求头里没有 grpc-timeout']], ['格式'])),
    step("A → B → C 三层调用,客户端设 1 秒,A 和 B 各先处理 100 ms 再用收到的 ctx 调下一层:A 看到剩余 999 ms,B 看到剩余 898 ms,C 看到剩余 797 ms。每一跳都会把当前剩余时间写进新的 grpc-timeout,所以整条调用链共享同一个总时限,越往后的服务剩得越少。前提是每一层都把收到的 ctx 传给下游。", t=tl(S(2)), done=lidx(S(2), 'A 看到剩余'), b=bars([['A 看到剩余 ms', 999, '999'], ['B 看到剩余 ms', 898, '898'], ['C 看到剩余 ms', 797, '797']], 1000, done=[0, 1, 2]), kv=KV([['客户端设', '1000 ms'], ['A / B / C 看到的剩余', '999 / 898 / 797 ms'], ['前提', '每一层都把收到的 ctx 传给下游']], ['前提'])),
    step("如果 A 调 B 时没有传 ctx(用了 context.Background()),下游就没有截止时间。实验里客户端设 200 ms,B 要 300 ms 再调 C,C 要 400 ms:传递 ctx 时客户端 DeadlineExceeded 用时 201.1 ms,1.2 秒后 B 完成了 0 次、C 完成了 0 次——上游的取消传到了下游;不传 ctx 时客户端同样在 201.1 ms 超时,但 1.2 秒后 B 完成了 1 次、C 完成了 1 次——客户端早已放弃,下游还把活干完了。这是微服务里“超时了但后台还在跑”的典型来源。", t=tl(S(3)), done=lidx(S(3), 'A→B 传递 ctx=false'), mark=lidx(S(3), 'A→B 传递 ctx=true'), b=bars([['传 ctx:B 完成次数', 0, '0'], ['传 ctx:C 完成次数', 0, '0'], ['不传 ctx:B 完成次数', 1, '1'], ['不传 ctx:C 完成次数', 1, '1']], 1.2, mark=[0, 1], done=[2, 3]), kv=KV([['传递 ctx', '客户端超时后 B、C 都没有完成'], ['不传 ctx', '客户端超时,B、C 仍各完成 1 次'], ['后果', '白白消耗下游资源']], ['后果'])),
    step("截止时间已经过去 1 秒再发起调用:客户端立刻返回 code=DeadlineExceeded message=“context deadline exceeded”,用时 0.0 ms,线上的 HEADERS/DATA 帧 0 个——请求根本没有发出去。已经过期的调用不会浪费网络和服务端资源。", t=tl(S(4)), done=lidx(S(4), '已过期 1 秒的 deadline'), b=bars([['线上帧数', 0, '0'], ['用时 ms', 0, '0.0']], 1, done=[0, 1]), kv=KV([['过期 1 秒的 deadline', '立即 DeadlineExceeded,0.0 ms'], ['线上', 'HEADERS/DATA 帧 0 个'], ['含义', '请求没有发出去']], ['含义'])),
    step("服务端能不能知道客户端已超时:客户端 150 ms 超时,handler 里监听 ctx.Done() 的版本,客户端 151.1 ms 返回,服务端在 151.1 ms 时发现 ctx 已取消,可以立刻放弃;不监听 ctx 的版本,客户端同样在 150.6 ms 返回,但 1.1 秒后服务端仍把 1 秒的活干完了(完成次数 1)。取消和超时通过 RST_STREAM 通知服务端,服务端的 ctx 被取消;handler 不去看 ctx,就看不到。", t=tl(S(5)), done=lidx(S(5), '监听 ctx.Done()'), mark=lidx(S(5), '不监听 ctx'), b=bars([['监听 ctx:服务端发现取消的时刻 ms', 151.1, '151.1'], ['不监听:服务端多干的活 ms', 1000, '1000']], 1000, done=[0], mark=[1]), kv=KV([['监听 ctx.Done()', '151.1 ms 就发现取消'], ['不监听', '仍把 1 秒的活干完'], ['通知方式', 'RST_STREAM,服务端 ctx 被取消']], ['监听 ctx.Done()'])),
    step("截止时间在线上是相对时长而不是绝对时间点,服务端从收到请求头那一刻起重新计时,传输延迟不会被扣掉。代理给客户端到服务端方向加延迟(每个数据块转发前等待,HEADERS 和 DATA 各一次):延迟 0 时,服务端 handler 看到剩余 999 ms,此刻客户端真正剩 999 ms;延迟 100 ms 时,服务端看到的仍是 999 ms,而客户端此刻只剩 798 ms;延迟 300 ms 时,服务端看到 999 ms,客户端只剩 598 ms。服务端的截止时间比客户端的晚了传输延迟那么多;好处是不依赖两台机器的时钟同步。", t=tl(S(6)), done=lidx(S(6), '300ms'), mark=lidx(S(6), '0s '), b=bars([['延迟 0:客户端剩余 ms', 999, '999'], ['延迟 100 ms:客户端剩余', 798, '798'], ['延迟 300 ms:客户端剩余', 598, '598'], ['服务端看到(三种都是)', 999, '999']], 1000, mark=[1, 2], done=[3]), kv=KV([['服务端看到的剩余', '三种延迟下都是 999 ms'], ['客户端真正剩余', '999 / 798 / 598 ms'], ['原因', '相对时长,服务端收到时重新计时']], ['原因'])),
]
A = mkarth('h5', 5, 'gRPC,deadline,grpc-timeout,context,超时传播,Go,真实验证,动画演示',
    '实测 gRPC 的 deadline:线上是最多 8 位数字加单位字母的相对时长(999978u);A→B→C 逐跳扣减(999、898、797 ms);中间一层不传 ctx,客户端超时后下游还会把活干完;已过期的调用不发任何帧;服务端不监听 ctx 就看不到取消;传输延迟不会被扣掉。',
    '客户端设了 1 秒超时,这个截止时间怎么穿过三层服务?线上是什么格式?中间一层忘了传 context 会怎样?服务端怎么知道客户端已经放弃?这篇用抓包和三层调用逐个验证。',
    [('999978u', '1 秒的 context 超时在线上 grpc-timeout 头里的值(发出那一刻剩下的微秒数)'), ('999 → 898 → 797 ms', '客户端设 1 秒,A、B、C 三层各自看到的剩余时间'), ('0 对 1', '客户端 200 ms 超时后,传递 ctx 与不传 ctx 时下游 B 最终完成的次数')],
    [('线上格式', '<p>grpc-timeout 是“最多 8 位数字 + 单位字母”的相对时长。写入的是发出调用那一刻 ctx 里剩余的时间。没有设截止时间的调用不带这个头。</p>'),
     ('跨服务传播', '<p>每一跳把当前剩余时间写进新的 grpc-timeout,调用链共享同一个总时限。前提是每层把收到的 ctx 传给下游。</p>'),
     ('不传 ctx 的后果', '<p>A 调 B 时用 context.Background(),下游没有截止时间,上游超时取消也传不到下游;客户端已经放弃,B 和 C 还各完成了 1 次。</p>'),
     ('过期的调用', '<p>截止时间已过的调用在客户端本地就返回 DeadlineExceeded,0 帧上线。</p>'),
     ('服务端要自己看 ctx', '<p>客户端超时或取消会通过 RST_STREAM 取消服务端的 ctx,但 handler 不监听 ctx.Done() 就不会停,会把 1 秒的活干完。长耗时的 handler 要在循环或阻塞处检查 ctx。</p>'),
     ('相对时长', '<p>因为线上传的是相对时长,不需要两台机器时钟同步,代价是传输延迟不会被扣除:服务端的截止时间比客户端的晚了传输那一段。所以每一层都应该给下游留出余量(超时预算,见弹性系列)。</p>')],
    steps,
    [ENV_H + '。第六节用抓包代理给客户端到服务端方向加了固定延迟(每个数据块转发前等待,所以 HEADERS 和 DATA 各被延迟一次,100 ms 的延迟让请求晚到约 200 ms);其余各节为真实调用;耗时为单次测量,几 ms 的波动属正常',
     '没有验证:其它语言实现对 grpc-timeout 的取整;网关或代理在转发时是否改写 grpc-timeout;服务端用 grpc.MaxConnectionAge 等配置对在途调用的影响;WaitForReady 与 deadline 的交互(第 3 篇已经看过)'],
    'deadline')
